from duration import parse_duration as p
valid = {
 "1h30m":5400, " 2d 4h ":187200, "1.5h":5400, "1w2d3h4m5s":788645,
 "1:02:03":3723, "-45s":-45, "0":0, "1.5m":90, "0.1h":360, "90:00":5400,
 "1:30":90, "1:00:00":3600, "05m":300, "-1h":-3600, "-1:30":-90, "-0s":0,
 "0.25h":900, "1h30m20s":5420, "1h 30m":5400, "0s":0, "0.0h":0,
}
for s, want in valid.items():
    got = p(s)
    assert got == want, (s, got, want)
invalid = ["", "   ", "5", "1.5", ".5h", "5.h", "1 h", "1h  30m", "30m1h",
 "1h1h", "0.3s", "1:60", "1:5", "+1h", "--1h", "1h,30m", "1H", "1", "1h-30m",
 "1:2:03", "1:00:60", "1:", ":30", "1h 30", "1.2.3h", "1 h 30 m", "1:000"]
for s in invalid:
    try:
        p(s)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError: %r" % s)
for bad in [None, 5, 1.5, b"1h"]:
    try:
        p(bad)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError: %r" % (bad,))
print("all ok")
